declare(strict_types=1);require_once __DIR__.'/_funcoes.php';exigir_permissao('ponto.visualizar');$erro='';$editar=(int)($_GET['editar']??0);$s=$pdo->prepare('SELECT * FROM ponto_ocorrencias WHERE id=:id');$s->execute([':id'=>$editar]);$atual=$s->fetch()?:[];
if($_SERVER['REQUEST_METHOD']==='POST'){exigir_permissao('ponto.editar');validar_csrf();try{$id=(int)($_POST['id']??0);$tipo=trim($_POST['tipo']??'');$situacao=trim($_POST['situacao']??'');$tipos=['troca_loja','convocacao_folga','bilhete_perdido','integracao','treinamento','divergencia_rhid','outra'];if(!in_array($tipo,$tipos,true)||!in_array($situacao,['aberta','resolvida'],true))throw new RuntimeException('Tipo ou situação inválida.');$origem=(int)($_POST['ponto_id']??0);if($origem&&!ponto_buscar_ponto($pdo,$origem))throw new RuntimeException('Ponto vinculado inválido.');$descricao=trim($_POST['descricao']??'');$resolucao=trim($_POST['resolucao']??'');if($descricao==='')throw new RuntimeException('A descrição é obrigatória.');if($situacao==='resolvida'&&$resolucao==='')throw new RuntimeException('Informe a resolução.');$dados=['ponto_id'=>$origem?:null,'data'=>ponto_validar_data($_POST['data']??''),'tipo'=>$tipo,'descricao'=>$descricao,'situacao'=>$situacao,'resolucao'=>$resolucao?:null];if($id){$dados['id']=$id;$pdo->prepare('UPDATE ponto_ocorrencias SET ponto_id=:ponto_id,data=:data,tipo=:tipo,descricao=:descricao,situacao=:situacao,resolucao=:resolucao WHERE id=:id')->execute($dados);ponto_historico($pdo,'ponto_ocorrencias',$id,'edicao',$atual,$dados,$resolucao?:null);}else{$pdo->prepare('INSERT INTO ponto_ocorrencias (ponto_id,data,tipo,descricao,situacao,resolucao) VALUES (:ponto_id,:data,:tipo,:descricao,:situacao,:resolucao)')->execute($dados);$id=(int)$pdo->lastInsertId();ponto_historico($pdo,'ponto_ocorrencias',$id,'criacao',[],$dados);}registrar_auditoria('ponto','ocorrencia_salva','ponto_ocorrencias',$id,$atual,$dados);redirect('ocorrencias.php?salvo=1');}catch(Throwable $e){$erro=ponto_mensagem_erro($e);$atual=array_merge($atual,$_POST);}}
$lista=$pdo->query('SELECT o.*,p.data AS ponto_data FROM ponto_ocorrencias o LEFT JOIN pontos_trabalho p ON p.id=o.ponto_id ORDER BY o.data DESC,o.id DESC')->fetchAll();$labels=['troca_loja'=>'Troca de loja','convocacao_folga'=>'Convocação na folga','bilhete_perdido'=>'Bilhete perdido','integracao'=>'Integração','treinamento'=>'Treinamento','divergencia_rhid'=>'Divergência com RHID','outra'=>'Outra'];
